SELECT 1164742 AS org, q.role AS role, q.sec AS sec, count(*) AS party_rows, count(DISTINCT q.tid) AS tenders, count(DISTINCT q.nid) AS notices FROM (SELECT p.role AS role, substr(p.mention_section_id, 1, 3) AS sec, p.tender_id AS tid, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1164742 AND p.seq = t.current_seq LIMIT 20000) q GROUP BY q.role, q.sec UNION ALL SELECT 1171563 AS org, q.role AS role, q.sec AS sec, count(*) AS party_rows, count(DISTINCT q.tid) AS tenders, count(DISTINCT q.nid) AS notices FROM (SELECT p.role AS role, substr(p.mention_section_id, 1, 3) AS sec, p.tender_id AS tid, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1171563 AND p.seq = t.current_seq LIMIT 20000) q GROUP BY q.role, q.sec UNION ALL SELECT 1182792 AS org, q.role AS role, q.sec AS sec, count(*) AS party_rows, count(DISTINCT q.tid) AS tenders, count(DISTINCT q.nid) AS notices FROM (SELECT p.role AS role, substr(p.mention_section_id, 1, 3) AS sec, p.tender_id AS tid, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1182792 AND p.seq = t.current_seq LIMIT 20000) q GROUP BY q.role, q.sec UNION ALL SELECT 5766 AS org, q.role AS role, q.sec AS sec, count(*) AS party_rows, count(DISTINCT q.tid) AS tenders, count(DISTINCT q.nid) AS notices FROM (SELECT p.role AS role, substr(p.mention_section_id, 1, 3) AS sec, p.tender_id AS tid, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 5766 AND p.seq = t.current_seq LIMIT 20000) q GROUP BY q.role, q.sec UNION ALL SELECT 1166638 AS org, q.role AS role, q.sec AS sec, count(*) AS party_rows, count(DISTINCT q.tid) AS tenders, count(DISTINCT q.nid) AS notices FROM (SELECT p.role AS role, substr(p.mention_section_id, 1, 3) AS sec, p.tender_id AS tid, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1166638 AND p.seq = t.current_seq LIMIT 20000) q GROUP BY q.role, q.sec
